/** Find a part by its stable warehouse locator.
 * @param locator - Stable identifier such as warehouse.hex-head-bolt.
 * @returns The matching part, or undefined when the locator is unknown.
 * @public
 */
export const findWarehousePart = (locator: string): WarehousePart | undefined => warehouseParts.find((part) => part.locator === locator);
